async function save(a,key=''){const q=++seq;sync('saving','保存中...');rowState(key,'saving');if(MODE==='local'){const i=warehouse.findIndex(x=>x.id===a.id);if(i>=0)warehouse[i]=a;else warehouse.push(a);persistLocal();if(q===seq)sync('saved',`已保存 ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`);rowState(key,'saved');return}try{const r=await fetch('/api/apps/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app:a})}),j=await r.json();if(!j.success)throw Error(j.message);if(q===seq)sync('saved',`已同步 ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`);rowState(key,'saved')}catch(e){sync('error','保存失败');toast(`保存失败：${e.message}`)}}
