async function load(){if(location.hostname.endsWith('.github.io')||location.protocol==='file:'){modeLocal('静态部署 · 数据保存在当前浏览器');return}try{const r=await fetch('/api/apps');if(r.status===404)throw Object.assign(new Error('HTTP 404'),{code:404});if(!r.ok)throw Error('HTTP '+r.status);const txt=await r.text();let j;try{j=JSON.parse(txt)}catch{throw Error('响应非 JSON：'+txt.slice(0,120))}if(!j||j.success===false||!Array.isArray(j.data))throw Error((j&&j.message)||'数据格式异常');MODE='server';warehouse=j.data.filter(a=>a&&typeof a.name==='string');if(warehouse.length<j.data.length)console.warn('[load] 已忽略',j.data.length-warehouse.length,'个缺少 name 的应用条目');hydrate();render();return}catch(e){modeLocal(`API 不可用（${e?.code||'无法连接'}），已改用浏览器本地存储`)}}
