function placementView(){let p=placement(),next=Math.max(0,...segments().map(s=>+s.priority))+1,onAll=openCount()>0,total=segments().length,list=state.pendingOnly?segments().filter(s=>(s.idConfigs||[]).some(c=>!c.placementId)):segments();return `<section class="data-surface"><header class="surface-head"><div><h2>流量分组</h2><span>${p.mediation} · ${total} 个 Waterfall 分组${state.pendingOnly?` · 仅显示 ${list.length} 个待回填`:''}</span></div><div class="head-actions">${state.pendingOnly?`<button class="filter-chip" data-filter-pending>仅看待回填 ×</button>`:''}<button class="text-action" data-toggle-all>${onAll?'∨ 全部收起':'∧ 全部展开'}</button><span class="expand-count">${openCount()}/${total} 已展开</span><button class="text-action" data-add="segment">＋ 新增流量分组</button></div></header><div class="segment-list">${list.map(s=>{const filled=s.idConfigs?.filter(c=>c.placementId)?.length||0,total=s.idConfigs?.length||0,st=!total?'empty':filled>=total?'ok':'partial',ph=!total?`待配置`:filled>=total?`✓ ${filled}/${total} 组 · 全部就绪`:`! ${filled}/${total} 组 · 待回填`,open=!!state.open[s.id],tier=s.priority<=3?1:s.priority<=7?2:3;return `<div class="accordion-row ${open?'open':''}" data-seg="${s.id}" data-acc="${s.id}"><span class="acc-toggle">${open?'▼':'▶'}</span><span class="priority-badge tier-${tier}">P${s.priority}</span><div class="segment-main"><strong>${esc(s.name)}</strong> <small>${total} 组 ID · P${s.priority}</small></div><span class="progress-pill state-${st}">${ph}</span><label class="ecpm-editor">$ <input type="number" step=".5" min="0" value="${Number(s.eCPM)||0}" data-ecpm="${s.id}"></label><div class="acc-actions"><button class="acc-badge" data-acc="${s.id}">${open?'收起':'展开'}<span>▾</span></button></div></div>${open?`<div class="accordion-body" data-seg="${s.id}">${segmentPanel(s)}</div>`:''}`}).join('')}${!list.length&&draft?.type!=='segment'?`<div class="empty-state">${state.pendingOnly?'已全部就绪 · 无待回填分组':'暂无流量分组 · 点击 [＋ 新增流量分组] 或按 <kbd>N</kbd> 开始'}</div>`:''}${draft?.type==='segment'?`<div class="draft-row segment-draft" data-draft-type="segment"><span class="acc-toggle">●</span><span class="priority-badge">P${next}</span>${input('name','分组名称（必填）')}<label class="ecpm-editor">$ ${input('eCPM','','20','type="number" step=".5"')}</label><div class="acc-actions"><button class="submit-badge" data-draft-commit>↵ 创建</button></div></div>`:''}</div></section>`}
function segmentPanel(s){const total=s.idConfigs?.length||0,filled=s.idConfigs?.filter(c=>c.placementId)?.length||0;return `<div class="panel-head"><span class="panel-title">ID 配置矩阵 · 参考 eCPM $${Number(s.eCPM||0).toFixed(2)} · 已完成 ${filled}/${total}</span><div class="panel-actions seg-actions"><button class="seg-btn" data-batch-add title="为当前分组生成 L/H/M 各 N 条配置（覆盖原配置）">⚡ 批量生成</button><button class="seg-btn" data-export-menu title="复制当前分组全部列（TSV）">⧉ 批量导出 ▾</button>${state.exportMenu===s.id?`<div class="export-menu"><button class="export-item" data-export-tsv="${s.id}">⧉ 一键复制全部列<small>制表符分隔 · 可直接贴入 Excel</small></button></div>`:''}</div></div><div class="table-scroll"><table class="config-table"><thead><tr><th>序号</th><th>广告源</th><th>组标识</th>${thCol('底价','floorPrice','copy')}${thCol('广告名称','adName','copy')}${thCol('广告 ID','placementId','both')}${thCol('Meta 来源 ID','metaSourceId','both')}<th>联动</th><th></th></tr></thead><tbody>${(s.idConfigs||[]).map((c,i)=>`<tr class="config-row${i>0&&s.idConfigs[i-1].groupTag!==c.groupTag?' tier-start':''}" data-tier="${c.groupTag}" data-row-key="${c.id}"><td class="idx">#${i+1}</td><td><span class="network-tag ${netClass(c.network)}">${esc(c.network)}</span></td><td><div class="tag-toggle">${['L','H','M'].map(t=>`<button class="${c.groupTag===t?'active':''}" data-tag="${t}" data-id="${c.id}">${t}</button>`).join('')}</div></td><td class="linked-value">$${Number(c.floorPrice).toFixed(2)}</td><td class="linked-value ad-name">${esc(c.adName)}</td><td><input value="${esc(c.placementId)}" data-field="placementId" data-id="${c.id}" placeholder="待回填 ID" class="${c.placementId?'cell-filled':'cell-empty'}"></td><td><input value="${esc(c.metaSourceId)}" data-field="metaSourceId" data-id="${c.id}" placeholder="可选"></td><td><button class="lock-action" data-lock="${c.id}">${c.isLocked!==false?'🔒':'🔓'}</button></td><td><button class="icon-action" data-delete-config="${c.id}">×</button></td></tr>`).join('')}${draft?.type==='id'&&draft?.seg===s.id?`<tr class="draft-row config-row" data-draft-type="id"><td class="idx">#${total+1}</td><td><span class="network-tag net-admob">Admob</span></td><td><div class="tag-toggle">${['L','H','M'].map(t=>`<button class="tag-btn ${t==='H'?'active':''}" data-draft-tag="${t}">${t}</button>`).join('')}</div></td><td>$${Number(s.eCPM||0).toFixed(2)}</td><td>名称自动生成</td><td>${input('placementId','待回填 ID')}</td><td>${input('metaSourceId','可选')}</td><td>🔒</td><td></td></tr>`:''}${draft?.type==='batch'&&draft?.seg===s.id?`<tr class="draft-row config-row" data-draft-type="batch"><td colspan="4" style="white-space:nowrap">批量生成 L/H/M 各 <input data-draft-field="count" placeholder="n" style="width:64px"> 个（共 3n 条，Admob）</td><td colspan="5">Enter 生成 · Esc 取消</td></tr>`:''}</tbody></table></div>${draft?.type!=='id'&&draft?.type!=='batch'?add('id','快速添加一个 ID 槽位'):''}`}
const OPST={idle:{label:'未创建',cls:'st-idle'},running:{label:'运行中',cls:'st-running'},mediation:{label:'中介组未建',cls:'st-medi'},meta:{label:'Meta未建',cls:'st-meta'}},OPORDER=['running','idle','mediation','meta'],TAGORD={L:0,M:1,H:2};
const opstOf=c=>OPST[c.opState]?c.opState:'idle';
function findCfg(id){for(const a of warehouse){for(const c of ids(a))if(c.id===id)return{a,c}}return{}}
function ccRows(){const q=(($('#search')||{}).value||'').trim().toLowerCase(),cc=state.cc,out=[];warehouse.forEach(a=>{if(cc.app&&a.id!==cc.app)return;(a.formats||[]).forEach(f=>(f.placements||[]).forEach(p=>{if(cc.placement&&p.id!==cc.placement)return;(p.segments||[]).forEach(s=>(s.idConfigs||[]).forEach(c=>{if(cc.tag&&c.groupTag!==cc.tag)return;if(q){const hay=(a.name+' '+p.code+' '+f.name+' '+s.name+' '+String(c.adName||'')+' '+String(c.placementId||'')+' '+String(c.metaSourceId||'')).toLowerCase();if(!hay.includes(q))return}out.push({a,p,s,c})}))}))});const tg=x=>TAGORD[x.c.groupTag]??9,nm=(x,y)=>String(x.a.name).localeCompare(String(y.a.name)),by={tag:(x,y)=>tg(x)-tg(y)||nm(x,y)||x.s.priority-y.s.priority||y.c.floorPrice-x.c.floorPrice,price:(x,y)=>y.c.floorPrice-x.c.floorPrice||tg(x)-tg(y)||nm(x,y),pri:(x,y)=>x.s.priority-y.s.priority||nm(x,y)||tg(x)-tg(y)};return out.sort(by[cc.sort]||by.tag)}
function ccFmt(tpl,r){return String(tpl||'').replace(/\{(应用|广告位|层级|标识|底价|广告名称|广告ID|Meta来源ID|Meta ID|MetaID)\}/g,(m,k)=>({应用:r.a.name,广告位:r.p.code,层级:'P'+r.s.priority,标识:r.c.groupTag,底价:Number(r.c.floorPrice||0).toFixed(2),广告名称:r.c.adName||'',广告ID:r.c.placementId||'',MetaID:r.c.metaSourceId||'','Meta ID':r.c.metaSourceId||'','Meta来源ID':r.c.metaSourceId||''}[k]??''))}
function ccPrev(tpl){return ccFmt(tpl,ccRows()[0]||{a:{name:'应用代号'},p:{code:'PLACEMENT'},s:{priority:1},c:{groupTag:'L',floorPrice:12.5,adName:'示例_广告名称',placementId:'ca-app-pub-xxx',metaSourceId:'meta_xxx'}})}
function ccTplPanel(){if(!state.ccTpl)return'';const tpl=localStorage.getItem('ccTpl')||'{广告名称} | {广告ID} | {底价}';return `<div class="cc-tpl-pop"><b>⚙️ 自定义复制模板</b><input id="ccTplInput" value="${esc(tpl)}" spellcheck="false" placeholder="{广告名称} | {广告ID} | {底价}"><div class="cc-tpl-legend">可用占位符：{应用} {广告位} {层级} {标识} {底价} {广告名称} {广告ID} {Meta ID}（实时预览第一行）</div><div class="cc-tpl-prev" id="ccTplPrev">${esc(ccPrev(tpl))}</div><button class="primary-btn" data-cc-tpl-copy>📋 按模板复制（有勾选用勾选，否则全部筛选结果）</button></div>`}
function stPill(c){const o=OPST[opstOf(c)];return `<span class="cc-st-wrap"><button class="cc-status-btn ${o.cls}" data-cc-menu="${c.id}" title="点击切换业务状态"><i class="st-dot"></i>${o.label}<span class="cc-caret">▾</span></button></span>`}
function stMenu(c){const m=state.ccMenu;return `<div class="cc-st-menu" style="left:${m.x}px;top:${m.y}px">${OPORDER.map(k=>`<button class="cc-st-item${opstOf(c)===k?' cur':''}" data-cc-set="${k}" data-cc-id="${c.id}"><i class="st-dot"></i>${OPST[k].label}${opstOf(c)===k?'<span class="cc-check">✓</span>':''}</button>`).join('')}</div>`}
function ccRow(r,i){const{a,p,s,c}=r;return `<tr class="cc-row" data-row-key="${c.id}"><td class="cc-ck"><input type="checkbox" data-cc-check="${c.id}"${state.ccSel.has(c.id)?' checked':''}></td><td class="cc-idx">#${String(i+1).padStart(2,'0')}</td><td><div class="cc-app"><strong>${esc(a.name)}</strong><span class="cc-code">${esc(p.code)}</span></div></td><td class="cc-pri">P${s.priority}</td><td><span class="tag-badge tg-${c.groupTag}">${esc(c.groupTag)}</span></td><td class="cc-floor">$${Number(c.floorPrice).toFixed(2)}</td><td class="cc-cell"><span class="cc-txt" title="${esc(c.adName)}">${esc(c.adName)}</span><button class="cell-copy" data-quick-copy="${esc(c.adName)}" title="复制广告名称">📋</button></td><td class="cc-cell"><span class="cc-txt" title="${esc(c.placementId)}">${esc(c.placementId)||'<i class="cc-dim">未回填</i>'}</span>${c.placementId?`<button class="cell-copy" data-quick-copy="${esc(c.placementId)}" title="复制广告 ID">📋</button>`:''}</td><td class="cc-cell"><span class="cc-txt" title="${esc(c.metaSourceId)}">${esc(c.metaSourceId)||'<i class="cc-dim">未回填</i>'}</span>${c.metaSourceId?`<button class="cell-copy" data-quick-copy="${esc(c.metaSourceId)}" title="复制 Meta ID">📋</button>`:''}</td><td>${stPill(c)}${state.ccMenu&&state.ccMenu.id===c.id?stMenu(c):''}</td></tr>`}
function copyView(){const rows=ccRows(),vis=new Set(rows.map(r=>r.c.id));state.ccSel.forEach(id=>{if(!vis.has(id))state.ccSel.delete(id)});const cc=state.cc,tab=cc.tab,list=tab==='all'?rows:rows.filter(r=>opstOf(r.c)===tab),cnt={all:rows.length};OPORDER.forEach(k=>cnt[k]=0);rows.forEach(r=>cnt[opstOf(r.c)]++);const g={running:0,idle:0,pend:0};warehouse.flatMap(ids).forEach(c=>{const k=opstOf(c);if(k==='running')g.running++;else if(k==='idle')g.idle++;else g.pend++});const appIc=a=>a.iconState==='ok'&&a.icon&&MODE!=='local'?`<img src="/icons/${esc(a.icon)}" alt="" onerror="this.replaceWith(Object.assign(document.createElement('b'),{className:'pv-letter sm',textContent:'${pvOf(a.pkg||a.name)}'}))">`:`<b class="pv-letter sm">${esc(pvOf(a.pkg||a.name))}</b>`,appItem=(a,sel)=>`<button type="button" class="cc-appsel-item${sel?' cur':''}" data-cc-appsel="${esc(a.id)}"${sel?' aria-current="true"':''}><span class="cc-appsel-ic">${appIc(a)}</span><span class="cc-appsel-name">${esc(a.name)}</span>${sel?'<i class="cc-appsel-check" aria-hidden="true">✓</i>':''}</button>`,curA=cc.app?warehouse.find(x=>x.id===cc.app):null,appOptions=`<button type="button" class="cc-appsel-item${cc.app?'':' cur'}" data-cc-appsel=""${cc.app?'':' aria-current="true"'}><span class="cc-appsel-ic">▦</span><span class="cc-appsel-name">全部应用</span>${cc.app?'':'<i class="cc-appsel-check" aria-hidden="true">✓</i>'}</button>${warehouse.map(a=>appItem(a,a.id===cc.app)).join('')}`,appSel=`<span class="cc-appsel"><button type="button" class="cc-select cc-app-trigger" data-cc-app-trigger aria-haspopup="listbox"><span class="cc-appsel-ic">${curA?appIc(curA):'▦'}</span><span class="cc-appsel-label">${curA?esc(curA.name):'全部应用'}</span></button>${state.ccAppSel?`<div class="cc-appsel-pop" role="listbox">${appOptions}</div>`:''}</span>`,plSrc=cc.app?warehouse.filter(a=>a.id===cc.app):warehouse,plOpts=plSrc.map(a=>`<optgroup label="${esc(a.name)}">${placements(a).map(p=>`<option value="${esc(p.id)}"${cc.placement===p.id?' selected':''}>${esc(p.code)}</option>`).join('')}</optgroup>`).join(''),allChk=list.length>0&&list.every(r=>state.ccSel.has(r.c.id)),selN=state.ccSel.size,tabs=[['all','全部','d-all'],['running','运行中','d-running'],['idle','未创建','d-idle'],['mediation','中介组未建','d-medi'],['meta','Meta未建','d-meta']],TAGS=[['','全部'],['L','仅 L'],['M','仅 M'],['H','仅 H']],SORTS=[['tag','标识 (L-M-H) 升序'],['price','底价 (高→低)'],['pri','瀑布流层级 (P1→P8)']];
return `<section class="data-surface cc-surface"><header class="surface-head"><div><h2>📋 复制中心</h2><span>扁平化平铺全部 ID · 勾选后可批量打标 / 一键复制 · 勾选后 Ctrl+C 直取广告 ID</span></div><div class="head-actions"><span class="cc-overview" title="全库 ID 状态概况"><i class="st-dot d-running"></i>运行中 ${g.running}<em>·</em><i class="st-dot d-idle"></i>待建 ${g.idle}<em>·</em><i class="st-dot d-medi"></i>中介/Meta未建 ${g.pend}</span><span class="cc-tpl-wrap"><button class="text-action" data-cc-tpl-open title="自定义复制格式模板">⚙️ 格式模板</button>${ccTplPanel()}</span></div></header><div class="cc-filters">${appSel}<select class="cc-select" data-cc-placement aria-label="广告位筛选"${cc.app?'':' disabled'}><option value="">全部广告位</option>${plOpts}</select><span class="cc-seg">${TAGS.map(([v,l])=>`<button data-cc-tag="${v}" class="${cc.tag===v?'active':''}">${l}</button>`).join('')}</span><select class="cc-select" data-cc-sort aria-label="排序">${SORTS.map(([v,l])=>`<option value="${v}"${cc.sort===v?' selected':''}>排序：${l}</option>`).join('')}</select></div><div class="cc-tabs">${tabs.map(([v,l,d])=>`<button class="cc-tab${cc.tab===v?' active':''}" data-cc-tab="${v}"><i class="st-dot ${d}"></i>${l}<b>${cnt[v]}</b></button>`).join('')}</div>${selN?`<div class="cc-bulk"><label class="cc-alllbl"><input type="checkbox" data-cc-all${allChk?' checked':''}> 全选 ${list.length} 项</label><span class="cc-bulk-sep"></span><span class="cc-bulk-lbl">打状态:</span>${OPORDER.map(k=>`<button class="cc-bulk-btn ${OPST[k].cls}" data-cc-batch="${k}"><i class="st-dot"></i>${OPST[k].label}</button>`).join('')}<span class="cc-bulk-sep"></span><span class="cc-bulk-lbl">一键复制:</span><button class="cc-bulk-btn act" data-cc-fill title="向选中行按顺序回填广告 ID / Meta ID">📥 批量回填 (${selN})</button><button class="cc-bulk-btn act" data-cc-copy="id">📋 复制 ID (${selN})</button><button class="cc-bulk-btn act" data-cc-copy="name">📋 复制名称 (${selN})</button><button class="cc-bulk-btn act" data-cc-copy="floor">📋 复制底价 (${selN})</button><button class="cc-bulk-btn act" data-cc-copy="meta">📋 复制 Meta ID (${selN})</button><button class="cc-bulk-btn act" data-cc-copy="idfloor">📋 复制 ID+底价</button><button class="cc-bulk-btn act" data-cc-copy="excel">📊 导出 Excel</button></div>`:''}<div class="table-scroll cc-scroll"><table class="cc-table"><thead><tr><th class="cc-ck"><input type="checkbox" data-cc-all${allChk?' checked':''} title="全选当前筛选"></th><th>序号</th><th>应用 / 广告位</th><th>层级</th><th>标识</th><th>底价</th><th>广告名称</th><th>广告 ID</th><th>Meta ID</th><th>状态 (点击切换)</th></tr></thead><tbody>${list.map(ccRow).join('')||'<tr><td colspan="10" class="empty-state">当前筛选无匹配 ID · 请调整筛选或搜索条件</td></tr>'}</tbody></table></div></section>`}
function ccCopy(btn){const kind=btn.dataset.ccCopy,rows=ccRows().filter(r=>state.ccSel.has(r.c.id));if(!rows.length)return toast('请先勾选数据行');let text='',msg='';if(kind==='id'){const ids2=rows.map(r=>r.c.placementId).filter(Boolean);if(!ids2.length)return toast('选中行均无广告 ID');text=ids2.join('\n');msg=`已复制 ${ids2.length} 个广告 ID ✓`}else if(kind==='name'){text=rows.map(r=>r.c.adName).join('\n');msg=`已复制 ${rows.length} 个广告名称 ✓`}else if(kind==='idfloor'){text=rows.map(r=>`${r.c.placementId||''}\t${Number(r.c.floorPrice||0).toFixed(2)}`).join('\n');msg=`已复制 ${rows.length} 行 ID+底价（TSV）✓`}else if(kind==='floor'){text=rows.map(r=>Number(r.c.floorPrice||0).toFixed(2)).join('\n');msg=`已复制 ${rows.length} 行底价 ✓`}else if(kind==='meta'){const idsm=rows.map(r=>r.c.metaSourceId).filter(Boolean);if(!idsm.length)return toast('选中行均无 Meta 来源 ID');text=idsm.join('\n');msg=`已复制 ${idsm.length} 个 Meta ID ✓`}else{text=[['序号','应用','广告位','层级','标识','底价','广告名称','广告 ID','Meta 来源 ID','状态'].join('\t'),...rows.map((r,i)=>[`#${i+1}`,r.a.name,r.p.code,`P${r.s.priority}`,r.c.groupTag,Number(r.c.floorPrice||0).toFixed(2),r.c.adName||'',r.c.placementId||'',r.c.metaSourceId||'',OPST[opstOf(r.c)].label].join('\t'))].join('\n');msg=`已导出 ${rows.length} 行（TSV · 贴入 Excel 即成表格）✓`}navigator.clipboard.writeText(text).then(()=>{const orig=btn.innerHTML;btn.classList.add('copied');btn.textContent=kind==='excel'?`✓ 已导出 ${rows.length} 项`:`✓ 已复制 ${rows.length} 项`;setTimeout(()=>{btn.classList.remove('copied');btn.innerHTML=orig},1500);toast(msg)}).catch(()=>toast('复制失败'))}
function ccTplCopy(){const tpl=localStorage.getItem('ccTpl')||'{广告名称} | {广告ID} | {底价}',rows=state.ccSel.size?ccRows().filter(r=>state.ccSel.has(r.c.id)):ccRows();if(!rows.length)return toast('当前无可复制内容');navigator.clipboard.writeText(rows.map(r=>ccFmt(tpl,r)).join('\n')).then(()=>toast(`已按模板复制 ${rows.length} 行 ✓`)).catch(()=>toast('复制失败'))}
function render(){renderNav();$('#workspace').innerHTML=({apps:appsView,app:appView,placement:placementView,copy:copyView}[state.level])();
  if(state.level==='apps') document.querySelectorAll('[data-row-key]').forEach(r=>{const id=r.dataset.id,b=r.querySelector('[data-quick-copy]');if(b&&!r.querySelector('[data-edit-app]'))b.insertAdjacentHTML('beforebegin',`<button class="action-icon" data-edit-app="${esc(id)}" title="编辑应用">✎</button>`)});
  if(state.level==='app') document.querySelectorAll('[data-row-key]').forEach(r=>{const b=r.querySelector('[data-quick-copy]');if(b&&!r.querySelector('[data-edit-placement]'))b.insertAdjacentHTML('beforebegin',`<button class="action-icon" data-edit-placement="${esc(r.dataset.id)}" data-format-id="${esc(r.dataset.formatId)}" title="编辑广告位">✎</button>`)});
  if(state.level==='placement') { document.querySelectorAll('[data-acc]').forEach(r=>{if(!r.querySelector('[data-edit-segment]'))r.querySelector('.acc-actions')?.insertAdjacentHTML('afterbegin',`<button class="action-icon" data-edit-segment="${esc(r.dataset.acc)}" title="编辑流量分组">✎</button><button class="action-icon" data-delete-segment="${esc(r.dataset.acc)}" title="删除流量分组">×</button>`)}); document.querySelectorAll('[data-export-menu]').forEach(b=>{if(!b.parentElement.querySelector('[data-quick-lhm]'))b.insertAdjacentHTML('afterend',`<button class="seg-btn" data-quick-lhm title="快速添加 L/H/M 各一个 ID 槽位">＋ 快速添加 L/H/M</button>`)}); }
  requestAnimationFrame(()=>document.querySelector('[data-draft-field]')?.focus())}
async function editAppById(id){const a=warehouse.find(x=>x.id===id);if(!a)return;const name=prompt('应用名称',a.name);if(name===null)return;const next=name.trim();if(!next||next===a.name)return;if(warehouse.some(x=>x!==a&&x.name===next))return toast('应用名称已存在');const old=a.name;a.name=next;if(MODE!=='local')await fetch('/api/apps/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:old})});render();await save(a);toast('应用已更新 ✓')}
