async function doImport(){const rows=state.importRows,first=state.importModel;if(!rows||!first)return;const typeMap={},platMap={};document.querySelectorAll('#importOverlay [data-unk-type]').forEach(el=>{const v=el.value;if(v)typeMap[el.dataset.unkKey]=v});document.querySelectorAll('#importOverlay [data-plat-select]').forEach(el=>{if(el.value)platMap[el.dataset.platKey]=el.value});if(first.unknown.length){if(Object.keys(typeMap).length<first.unknown.length)return toast('请为每个无法识别的广告位选择广告类型');state.importModel=buildImportModel(rows,typeMap)}const m=state.importModel,t=applyImport(warehouse,m,platMap);const apps=[...new Set(t.touched.map(x=>x.app))];apps.forEach(a=>(a.formats||[]).forEach(f=>(f.placements||[]).forEach(p=>(p.segments||[]).forEach(s=>calc(a,p,s)))));$('#importOverlay').hidden=true;state.importModel=null;render();await Promise.all(apps.map(a=>save(a)));toast(`导入完成：新增 ${t.report.created.apps.length} 应用 / ${t.report.created.placements.length} 广告位 / ${t.report.created.segments.length} 分组 / ${t.report.created.ids.length} 条 ID${t.report.mismatches.length?`；${t.report.mismatches.length} 处底价已按公式修正`:''}`)}
function exportJSON(){const d=new Date(),f=`${d.getFullYear()}${('0'+(d.getMonth()+1)).slice(-2)}${('0'+d.getDate()).slice(-2)}-${('0'+d.getHours()).slice(-2)}${('0'+d.getMinutes()).slice(-2)}`,blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),apps:warehouse},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ad-id-warehouse-backup-${f}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast(`已导出 ${warehouse.length} 个应用备份`)}
const toApps=j=>{if(Array.isArray(j))return{apps:j,mode:'replace'};if(!j||typeof j!=='object')return null;if(Array.isArray(j.apps))return{apps:j.apps,mode:'replace'};if(Array.isArray(j.data?.apps))return{apps:j.data.apps,mode:'replace'};if(Array.isArray(j.data))return{apps:j.data,mode:'replace'};if(typeof j.name==='string')return{apps:[j],mode:'merge'};return null};
$('#importFile').addEventListener('change',async e=>{const files=[...e.target.files];e.target.value='';if(!files.length)return;const jsons=files.filter(f=>/\.json$/i.test(f.name));if(jsons.length){let imported=0;for(const f of jsons){let j;try{j=JSON.parse((await f.text()).replace(/^\uFEFF/,''))}catch{toast(`已跳过 ${f.name}：JSON 解析失败`);continue}const r=toApps(j);if(!r){toast(`已跳过 ${f.name}：不是可识别的备份格式（顶层字段：${j&&typeof j==='object'?Object.keys(j).join(', ')||'无':typeof j}）`);continue}if(r.mode==='replace'){if(warehouse.length&&!confirm(`「${f.name}」为整库备份，将覆盖当前 ${warehouse.length} 个应用，确认？`))continue;warehouse=r.apps.filter(a=>a&&typeof a.name==='string')}else{r.apps.filter(a=>a&&typeof a.name==='string').forEach(a=>{const i=warehouse.findIndex(x=>x.name===a.name);if(i>=0)warehouse[i]=a;else warehouse.push(a)})}imported+=r.apps.filter(a=>a&&typeof a.name==='string').length}if(files.length>jsons.length)toast(`已忽略 ${files.length-jsons.length} 个非 JSON 文件（Excel 仅支持单文件）`);if(!imported)return;hydrate();render();if(MODE==='local'){persistLocal();toast(`已批量导入 ${imported} 个应用（${jsons.length} 个文件，浏览器本地）`)}else{await Promise.all(warehouse.map(a=>save(a)));toast(`已批量导入 ${imported} 个应用（${jsons.length} 个文件）`)}return}if(files.length>1)return toast('Excel 导入一次仅支持 1 个文件');const f=files[0];try{const buf=await f.arrayBuffer(),{rows}=await parseXlsx(buf),m=buildImportModel(rows);if(!m.entries.length)return toast('未在表格中找到可导入的数据');state.importRows=rows;state.importModel=m;renderImport(m);$('#importOverlay').hidden=false}catch(err){toast('导入失败：'+err.message)}});
load();
document.addEventListener('click',async e=>{
  const appBtn=e.target.closest('[data-edit-app]'); if(appBtn){e.preventDefault();e.stopPropagation();return editAppById(appBtn.dataset.editApp)}
  const plBtn=e.target.closest('[data-edit-placement]'); if(plBtn){e.preventDefault();e.stopPropagation();return editPlacementById(plBtn.dataset.editPlacement,plBtn.dataset.formatId)}
  const sgBtn=e.target.closest('[data-edit-segment]'); if(sgBtn){e.preventDefault();e.stopPropagation();return editSegmentById(sgBtn.dataset.editSegment)}
  const delBtn=e.target.closest('[data-delete-segment]'); if(delBtn){e.preventDefault();e.stopPropagation();return deleteSegmentById(delBtn.dataset.deleteSegment)}
  const q=e.target.closest('[data-quick-lhm]'); if(q){e.preventDefault();e.stopPropagation();const sid=segOf(q),s=segments().find(x=>x.id===sid);if(!s)return;['L','H','M'].forEach(t=>s.idConfigs.push({id:uid('id'),network:'Admob',groupTag:t,placementId:'',metaSourceId:'',discountRatio:1,isLocked:true}));calc(app(),placement(),s);render();await save(app());toast('已快速添加 L/H/M 各 1 个 ID 槽位 ✓')}
},true);
